"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[169],{6169:(e,t,i)=>{i.d(t,{I:()=>a,IQ:()=>r,X_:()=>n,oo:()=>s,xl:()=>l,zv:()=>o});let a=[{id:"wool-shu",name:"Wool & Shu",blurb:"The cloth and the clothes — shu, pakol, chugha, waistcoat and shawl, all in handwoven wool from the Hindu Kush."},{id:"wood-craft",name:"Wood & Craft",blurb:"Walnut wood and the mulberry lute — the best-documented wooden crafts of Chitral."},{id:"home-weave",name:"Home & Weave",blurb:"Rugs, knitwear and small woven things for the house, in natural colours."},{id:"from-the-valleys",name:"From the Valleys",blurb:"The crafts of Baltistan, Hunza, Swat, Dir and the Kalash valleys — each piece named for its true home."},{id:"the-harvest",name:"The Harvest",blurb:"Dried fruits, oils, honey and teas of the northern valleys."},{id:"stones-of-the-north",name:"Stones of the North",blurb:"Gemstones of the northern mountains, shown rough as they leave the valleys."}],o=[{slug:"shu-cloth",name:"Handwoven Shu Cloth",collection:"wool-shu",featured:!0,shortDescription:"The cloth itself — hand-spun, handwoven wool in its natural colours.",description:"Shu — patti in Urdu — is the handwoven woollen cloth of Chitral, made from the wool of local Kari sheep. The documented making runs from washing the sheep in mountain streams, through shearing, carding and spinning, to warping outdoors and weaving on a wooden loom over some three weeks, then foot-fulling in the hot springs of Garam Chashma and sun-drying. The cloth is windproof and undyed-earthy: natural white, grey, black and brown, with walnut-dyed red as the one traditional accent. This is a concept study in a length of that cloth — not a stocked item, and not a claim about any one maker's work.",indicativePrice:null,availability:"unverified"},{slug:"chitrali-pakol",name:"Chitrali Pakol",collection:"wool-shu",featured:!0,shortDescription:"The flat-topped, rolled-brim wool cap of the Hindu Kush.",description:"The pakol is a soft wool cap with a flat crown and a thick rolled brim, in natural brown, black, grey or ivory wool — and in a walnut-dyed red. The brim rolls to fit and pulls down over the ears in the cold; a feather or a sprig of juniper is sometimes tucked into it. The cap's home is Gilgit–Chitral, from where it spread across the region. We make no claim for the old Alexander story about its origin: scholars do not support it. This is a concept study in the cap, not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"chugha-coat",name:"Shuqa Winter Coat",collection:"wool-shu",featured:!0,shortDescription:"A long wool overcoat in rough Khowari shu, for the cold months.",description:"The chugha — shuqa in Khowar — is a long, loose wool overcoat worn over shalwar kameez in winter, cut from the rougher Khowari shu. It is a shared garment of the Hindu Kush and Central Asia — in Hunza it is called choga — and we do not present it as unique to Chitral. This is a concept study in the coat, not a stocked item, and not a claim about any one maker's work.",indicativePrice:null,availability:"unverified"},{slug:"wool-waistcoat",name:"Woollen Waistcoat",collection:"wool-shu",featured:!0,shortDescription:"A waistcoat in handwoven shu, worn with the pakol.",description:"The waistcoat is part of the documented winter dress of Chitral: a woollen waistcoat over a loose shirt, with the pakol and, in the coldest months, the chugha over all. This is a concept study in that waistcoat, in handwoven shu in the natural colours of the flock — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"womens-shu-shawl",name:"Women's Shu Shawl",collection:"wool-shu",featured:!0,shortDescription:"A shawl in handwoven wool, in the natural colours of the flock.",description:"Women's shawls in handwoven shu are part of the documented textile life of Chitral, alongside the everyday shalwar kameez now worn. The one embroidered object we can point to is a red topi in the Museum of Anthropology in Vancouver — so this shawl study stays plain, in natural wool, with no invented embroidery or motif. This is a concept study, not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"chitrali-sitar",name:"Chitrali Sitar",collection:"wood-craft",featured:!0,shortDescription:"The mulberry-wood lute of Sonoghor — unrelated to the Indian sitar.",description:"The Chitrali sitar is a long-necked lute carved from mulberry wood, with five strings in three courses tuned cc g cc, and a middle string that passes under the first four frets. It is made in Sonoghor village in Upper Chitral, by families who have made it for five or six generations, one instrument taking two to three weeks; it is played in tea rooms to accompany Khowar singing. Its name comes from the Central Asian setar, not from the Indian sitar. This is a concept study in the instrument, not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"walnut-wood-box",name:"Walnut-Wood Box",collection:"wood-craft",featured:!1,shortDescription:"A concept study in Chitral's walnut woodwork.",description:"Walnut-wood furniture is the best-attested non-textile craft of Chitral, and carved woodwork appears in the pillars and beams of traditional houses, in doors and in wooden storechests. This box is a concept study in that woodwork: its form is ours, not a documented traditional design, and no traditional motif is claimed for it. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"goathair-rug",name:"Goathair Rug",collection:"home-weave",featured:!1,shortDescription:"A floor covering woven from goathair, in natural colours.",description:"Goathair rugs are a documented traditional floor covering of Chitral houses, woven in patterns of natural colours. We show a concept in natural brown, grey and cream, and claim no specific traditional pattern for it — none is documented in the sources we have. This is a concept study, not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"wool-sweater",name:"Hand-Knitted Wool Sweater",collection:"home-weave",featured:!1,shortDescription:"Knitted wool for cold mornings — sweaters, vests, gloves.",description:"Knitting and hosiery are documented Chitrali crafts, and sweaters, vests, gloves and warmers are among the most in-demand woollen goods of the valley. This is a concept study in undyed natural wool, not a stocked item, and not a claim about any one maker's work.",indicativePrice:null,availability:"unverified"},{slug:"shu-purse",name:"Shu Cloth Purse",collection:"home-weave",featured:!1,shortDescription:"A small purse in handwoven shu.",description:"Purses and bags are made from shu alongside coats, caps and shawls. This is a small concept study in the cloth, in natural brown and grey wool — not a stocked item, and not a claim about any one maker's work.",indicativePrice:null,availability:"unverified"},{slug:"shu-blanket",name:"Handwoven Shu Blanket",collection:"wool-shu",featured:!1,shortDescription:"A length of handwoven shu, made up as a blanket.",description:"Shu is documented as the handwoven woollen cloth of Chitral, woven in lengths on wooden looms and fulled until dense and windproof. This blanket is a concept study in that cloth — a length of it made up as a blanket. The blanket form is ours; we claim no documented traditional blanket design for it, and no motif. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"shu-tote-bag",name:"Shu Tote Bag",collection:"wool-shu",featured:!1,shortDescription:"A tote bag in handwoven shu.",description:"Purses and bags are made from shu alongside coats, caps and shawls. This tote is a concept study in the cloth, in natural brown wool — not a stocked item, and not a claim about any one maker's work.",indicativePrice:null,availability:"unverified"},{slug:"wool-gloves",name:"Hand-Knitted Wool Gloves",collection:"wool-shu",featured:!1,shortDescription:"Knitted gloves in undyed natural wool.",description:"Knitting and hosiery are documented Chitrali crafts, and gloves are named among the most in-demand woollen goods of the valley, alongside vests, sweaters and warmers. This is a concept study in undyed natural wool — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"wool-vest",name:"Hand-Knitted Wool Vest",collection:"wool-shu",featured:!1,shortDescription:"A knitted vest in natural wool.",description:"Vests are named among the most in-demand knitted and hosiery goods of Chitral, alongside gloves, sweaters and warmers. This is a concept study in hand-knitted natural wool — not a stocked item, and not a claim about any one maker's work.",indicativePrice:null,availability:"unverified"},{slug:"wool-leggings",name:"Woollen Leggings",collection:"wool-shu",featured:!1,shortDescription:"Knitted woollen leggings for the cold months.",description:"Woollen leggings are documented as part of traditional winter dress in Chitral, worn with loose woollen trousers in the cold months, and warmers are named among the valley's in-demand hosiery. This is a concept study in hand-knitted natural wool — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"wool-yarn",name:"Hand-Spun Wool Yarn",collection:"wool-shu",featured:!1,shortDescription:"Hand-spun yarn in the natural colours of the flock.",description:"Spinning is one of the documented stages of making shu: carded wool is spun on a spinning wheel before warping and weaving. This is a concept study in that hand-spun yarn, in the natural colours of the flock — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"walnut-red-pakol",name:"Walnut-Red Pakol",collection:"wool-shu",featured:!1,shortDescription:"The pakol in walnut-dyed red — its best-attested coloured variant.",description:"The pakol is documented in natural brown, black, grey and ivory wool — and in a red dyed with walnut, the best-attested coloured variant of the cap. This is a concept study in that walnut-red cap, with the same flat crown and rolled brim — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"walnut-storechest",name:"Walnut-Wood Storechest",collection:"wood-craft",featured:!1,shortDescription:"A concept study in the wooden storechests of Chitrali houses.",description:"Wooden storechests — nakh chests for clothes and flour — are documented in traditional Chitrali houses, set on the corner platforms of the main room, and walnut-wood furniture is the best-attested non-textile craft of Chitral. This chest is a concept study in that woodwork: its form is ours, and no traditional motif is claimed for it. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"walnut-stool",name:"Walnut-Wood Stool",collection:"wood-craft",featured:!1,shortDescription:"A concept study in Chitral's walnut-wood furniture.",description:"Walnut-wood furniture is documented as popular in handicraft markets throughout the country, and carved woodwork appears in the pillars, beams and doors of traditional houses. This stool is a concept study in that woodwork: its form is ours, not a documented traditional design, and no motif is claimed for it. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"walnut-frame",name:"Walnut-Wood Frame",collection:"wood-craft",featured:!1,shortDescription:"A plain frame in walnut wood.",description:"Frames are listed among the tourist items made in Chitral, alongside cushions, and walnut wood is the valley's best-attested furniture wood. This frame is a concept study in plain walnut — its form is ours, and no traditional motif is claimed for it. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"weavers-shuttle",name:"Weaver's Shuttle",collection:"wood-craft",featured:!1,shortDescription:"The wooden shuttle that carries the weft across the loom.",description:"The shuttle is one of the documented tools of shu weaving: small spools called thasuruk sit inside it and carry the weft thread across the warp on the wooden loom. This is a concept study in that tool, in plain wood — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"carding-bow",name:"Carding Bow",collection:"wood-craft",featured:!1,shortDescription:"The bow that cards the wool before spinning.",description:"Carding is a documented stage of making shu: after washing and shearing, the wool is carded — with a carding bow, plucked to vibrate and separate the filaments — before spinning. This is a concept study in that tool — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"willow-basket",name:"Willow-Bark Basket",collection:"wood-craft",featured:!1,shortDescription:"A basket for dyed wool, after the reported warketi.",description:"A willow-bark basket called warketi is reported for holding dyed wool in the making of shu, in a secondary source we treat with caution. This basket is a concept study on that report — not a stocked item, and not a claim about any one maker's work.",indicativePrice:null,availability:"unverified"},{slug:"wool-cotton-rug",name:"Wool-and-Cotton Rug",collection:"home-weave",featured:!1,shortDescription:"A traditional floor covering in natural and walnut-dyed colours.",description:"Wool-with-cotton rugs in dyed colours are documented, with goathair rugs, as the traditional floor coverings of Chitral houses. This is a concept study in natural and walnut-dyed colours, and we claim no specific traditional pattern for it — none is documented in the sources we have. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"shu-cushion-cover",name:"Shu Cushion Cover",collection:"home-weave",featured:!1,shortDescription:"A cushion cover in handwoven shu.",description:"Cushions are listed among the tourist items made in Chitral, alongside frames, and shu is the valley's documented handwoven woollen cloth. This cushion cover is a concept study in that cloth, in natural colours — not a stocked item, and not a claim about any one maker's work.",indicativePrice:null,availability:"unverified"},{slug:"shu-prayer-mat",name:"Shu Prayer Mat",collection:"home-weave",featured:!1,shortDescription:"A plain prayer mat in handwoven shu.",description:"Prayer carpets are documented in traditional Chitrali houses, spread on the prayer platform of the main room. This mat is a concept study in handwoven shu, plain and in natural colours — its form is ours, and no traditional pattern is claimed for it. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"wool-socks",name:"Hand-Knitted Wool Socks",collection:"home-weave",featured:!1,shortDescription:"Knitted socks in undyed natural wool.",description:"Knitting and hosiery are documented Chitrali crafts, with sweaters, vests, gloves and warmers named among the valley's most in-demand woollen goods. These socks are a concept study in that hosiery, in undyed natural wool — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"shu-throw",name:"Shu Throw",collection:"home-weave",featured:!1,shortDescription:"A length of shu made up as a throw for the home.",description:"Shu is documented as a dense, windproof handwoven woollen cloth in natural white, grey, black and brown. This throw is a concept study in that cloth — a length of it made up for the home. The throw form is ours; no traditional design or motif is claimed for it. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"felt-slippers",name:"Felted Wool Slippers",collection:"home-weave",featured:!1,shortDescription:"Slippers in felted natural wool.",description:"Felting is a documented stage of making shu: after weaving, the cloth is fulled — kneaded and compressed, in Garam Chashma with the help of the hot springs — until it is dense and windproof. These slippers are a concept study in felted natural wool: the form is ours, not a documented traditional design. They are not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"crochet-shawl",name:"Hand-Crocheted Wool Shawl",collection:"home-weave",featured:!1,shortDescription:"A crocheted shawl in natural wool.",description:"Crochet is listed among the crafts of Chitral, alongside knitting and embroidery, and women's shawls are part of the documented textile life of the valley. This shawl is a concept study in hand-crocheted natural wool, plain and with no invented motif — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"balti-pattu",name:"Balti Pattu Cloth",collection:"from-the-valleys",featured:!1,shortDescription:"The handwoven woollen cloth of Baltistan, a craft now close to disappearing.",description:"Pattu — Balgos in Balti — is the documented woollen cloth of Baltistan: sheep are washed and shorn, the wool beaten clean, separated by fibre length, spun, woven and dyed with leaves and fruit. Researchers who interviewed more than thirty elders across Skardu, Shigar and Khaplu describe it as a dying art, with only a few people left who hold the knowledge. This is a concept study in that cloth, in natural colours — not a stocked item, and not Chitrali shu.",indicativePrice:null,availability:"unverified"},{slug:"karr-shawl",name:"Karr Shawl",collection:"from-the-valleys",featured:!1,shortDescription:"The thick woollen shawl of Baltistan.",description:"The Karr is the thick woollen shawl named among the traditional products of Baltistan's pattu weaving, worn by men and women against the cold. Like the cloth it comes from, it belongs to a craft described by researchers as close to disappearing. This is a concept study in plain natural wool — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"phima-felt",name:"Phima Felt",collection:"from-the-valleys",featured:!1,shortDescription:"Felted wool of Baltistan, beaten into cloth.",description:"Phima — namda — is Baltistan's felted wool: fibres are laid in crisscross layers and beaten with dampness and weight until they bind into cloth, used for garments and floor coverings. It is part of the same documented pattu tradition of Skardu and Shigar. This is a concept study in plain natural felt — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"islampur-shawl",name:"Islampur Dhussa Shawl",collection:"from-the-valleys",featured:!1,shortDescription:"The handloom woollen shawl of Islampur, Swat.",description:"Islampur village in Swat is documented as a handloom centre where almost every household weaves woollen shawls, blankets and dhussa from local sheep wool. Genuine handloom pieces are uneven in texture; power-loom copies sold under the same names are perfectly smooth. This is a concept study in plain natural wool — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"gilgiti-cap",name:"Gilgiti Cap",collection:"from-the-valleys",featured:!1,shortDescription:"The woollen cap of Gilgit-Baltistan.",description:"The Gilgiti cap is the handmade sheep-wool cap worn across Gilgit-Baltistan, a close relative of the pakol and documented as part of the region's woollen craft trade. This is a concept study in natural brown wool — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"dir-knife",name:"Dir Knife",collection:"from-the-valleys",featured:!1,shortDescription:"The hand-forged knife of Upper Dir.",description:"The Dir knife — Diroji — is hand-forged in Upper Dir, where several hundred small workshops and home smiths still make knives one at a time, each taking hours. The craft is documented as more than two hundred years old; the steel is bought from Wazirabad in Punjab and the handles are local wood, so this is Dir forging, not Dir steel. The knives are documented as popular with foreign travellers. This is a concept study — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"hunza-wood-utensils",name:"Hunza Apricot-Wood Utensils",collection:"from-the-valleys",featured:!1,shortDescription:"Bowls and spoons in Hunza fruitwood.",description:"Hunza's woodworkers are documented working in apricot, walnut, almond, cherry and pear timber, making boxes, bowls, dishes and serving utensils in Karimabad and Aliabad workshops. This is a concept study in plain apricot wood — its form is ours, and no traditional motif is claimed for it. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"bahrain-walnut-box",name:"Bahrain Walnut Box",collection:"from-the-valleys",featured:!1,shortDescription:"A walnut-wood box in the manner of Bahrain, Swat.",description:"Bahrain and Madyan in Swat are documented for hand-carved walnut and Kalami pine woodwork — doors, furniture, jewellery boxes and trays. This box is a concept study in plain walnut: its form is ours, and no traditional carved motif is claimed for it. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"kalash-twig-basket",name:"Kalash Twig Basket",collection:"from-the-valleys",featured:!1,shortDescription:"A basket of woven twigs from the Kalash valleys.",description:"Baskets and bags woven from twigs are documented among the handmade goods of the Kalash valleys, sold in the gift shops of Bumburet and Rumbur alongside Kalash dress and embroidery. The Kalash are a distinct people of southern Chitral — this is a Kalash piece, not a Chitrali one. This is a concept study — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"iraghi-cap",name:"Iraghi Cap",collection:"from-the-valleys",featured:!1,shortDescription:"The silk-embroidered women's cap of Hunza.",description:"The Iraghi — Phartsun in Burushaski — is the women's cap of Hunza, Nagar and Gilgit, worked in dense silk petit-point on cotton, traditionally taking months of handwork at a few hours a day, with the pattern carried in memory. Brides wear it with a silver front piece made by local jewellers. This is a concept study in the documented technique; the stitching shown is illustrative and no specific traditional pattern is claimed or reproduced. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"kalash-dress",name:"Kalash Dress",collection:"from-the-valleys",featured:!1,shortDescription:"The black robe and beadwork of Kalash women.",description:"Kalash women's dress — the long black robe called cou, embroidered with cowrie shells and coloured beads, with beaded headgear and layered glass-bead necklaces — is documented as gaining popularity with foreign visitors, who buy the attires in valley gift shops. The Kalash are a distinct people of southern Chitral, and ceremonial dress differs from pieces adapted for visitors. This is a concept study in the documented materials; no ceremonial design is claimed or reproduced. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"swati-embroidered-cushion",name:"Swati Embroidered Cushion Cover",collection:"from-the-valleys",featured:!1,shortDescription:"Cross-stitch embroidery from Swat.",description:"Swati embroidery is documented in the villages around Mingora, Matta and Kabal: geometric cross-stitch in deep red, black and gold on cotton and silk, made into cushion covers, dupattas and household pieces by women working from home and through cooperatives. It is Swat's own tradition — not Punjabi phulkari, whatever some guides call it. This is a concept study in the documented stitch and colours; no specific traditional pattern is claimed. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"hunza-embroidered-purse",name:"Hunza Embroidered Purse",collection:"from-the-valleys",featured:!1,shortDescription:"Do sutti embroidery from Hunza, made up as a purse.",description:"Hunza's do sutti — two-thread — embroidery began on caps and is now documented on wallets, purses, belts and cushion covers made for visitors and urban buyers, a tradition carried by generations of Hunza women and supported by local craft organisations. This is a concept study in the documented technique; the stitching shown is illustrative and no specific traditional pattern is claimed. It is not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"dried-apricots",name:"Dried Apricots",collection:"the-harvest",featured:!1,shortDescription:"Sun-dried apricots of the Hunza valley.",description:"Dried apricots are the signature produce of Hunza and Baltistan, dried in sun and shade — the unsulphured fruit dark brown, the sulphured orange — and sold in every valley bazaar from Karimabad to Skardu. Gilgit-Baltistan is reported to produce thousands of tonnes a year. These are presented as a concept study in the produce of the north — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"hunza-walnuts",name:"Hunza Walnuts",collection:"the-harvest",featured:!1,shortDescription:"Walnuts from the high valleys.",description:"Walnuts are documented among the great dry-fruit crops of Gilgit-Baltistan, sold in shell, halved and quartered in the bazaars of Hunza, Gilgit and Skardu, and pressed for oil. These are presented as a concept study in the produce of the north — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"hunza-almonds",name:"Hunza Almonds",collection:"the-harvest",featured:!1,shortDescription:"Almonds of Hunza and Baltistan.",description:"Almonds are documented alongside apricots and walnuts as a principal dry fruit of Hunza and Baltistan, sold dried and pressed for oil. These are presented as a concept study in the produce of the north — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"apricot-kernel-oil",name:"Apricot Kernel Oil",collection:"the-harvest",featured:!1,shortDescription:"Cold-pressed oil from apricot kernels.",description:"Apricot kernel oil, cold-pressed from the kernels of the northern apricot harvest, is documented in the bazaars of Hunza and Swat and in Pakistan's trade listings, used for cooking and skincare. This is presented as a concept study in the produce of the north — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"mountain-honey",name:"Mountain Honey",collection:"the-harvest",featured:!1,shortDescription:"Raw honey from the Hunza valley.",description:"Mountain honey is documented among the produce sold to visitors in Karimabad bazaar and listed by northern producers on Pakistan's trade portal. This is presented as a concept study in the produce of the north — not a stocked item, and no health claim is made for it.",indicativePrice:null,availability:"unverified"},{slug:"sea-buckthorn",name:"Sea Buckthorn",collection:"the-harvest",featured:!1,shortDescription:"The orange berry of the high valleys.",description:"Sea buckthorn grows wild in Hunza and Skardu and is documented as berries, pulp, juice, oil, powder and leaf tea, with northern producers exporting the oil. This is presented as a concept study in the produce of the north — not a stocked item, and no health claim is made for it.",indicativePrice:null,availability:"unverified"},{slug:"shilajit",name:"Shilajit",collection:"the-harvest",featured:!1,shortDescription:"The mountain resin of the high Karakoram and Hindu Kush.",description:"Shilajit — salajeet — is collected at high altitude in Chitral and Gilgit-Baltistan and documented as a significant regional export, sold as sun-dried resin and drops. We record that it is gathered and traded; we make no claim about its effects. This is presented as a concept study in the produce of the north — not a stocked item.",indicativePrice:null,availability:"unverified"},{slug:"hunza-herbal-tea",name:"Hunza Herbal Tea",collection:"the-harvest",featured:!1,shortDescription:"Dried mountain herbs for tea.",description:"Herbal teas — including the teas sold in Karimabad bazaar and listed by northern producers — are documented among the produce of Hunza, gathered and dried in the valley. This is presented as a concept study in the produce of the north — not a stocked item, and no health claim is made for it.",indicativePrice:null,availability:"unverified"},{slug:"swat-emerald",name:"Swat Emerald",collection:"stones-of-the-north",featured:!1,shortDescription:"Rough emerald from the Mingora mines.",description:"Emeralds have been mined at Mingora in Swat since 1958 — deep green stones of high clarity, documented as exported rough to Dubai and Thailand for cutting, and often sold onward as Indian or Jaipur emerald. What leaves Swat is rough stone; the cutting, and much of the value, happens abroad. This is a concept study in the rough stone — not a stocked item, and no origin is certified.",indicativePrice:null,availability:"unverified"},{slug:"aquamarine",name:"Aquamarine",collection:"stones-of-the-north",featured:!1,shortDescription:"Rough aquamarine from the Karakoram pegmatites.",description:"Aquamarine is documented among the gemstones of Gilgit-Baltistan's pegmatite fields — Shigar, Haramosh and the Braldu valley — mined on a small scale and traded rough through Gilgit and Skardu. This is a concept study in the rough crystal — not a stocked item, and no origin is certified.",indicativePrice:null,availability:"unverified"},{slug:"hunza-ruby",name:"Hunza Ruby",collection:"stones-of-the-north",featured:!1,shortDescription:"Ruby from the marbles of Hunza and Nagar.",description:"Ruby and spinel in marble are documented from Hunza and Nagar, among the thirty-two gemstones recorded for Gilgit-Baltistan, which produces the great majority of Pakistan's gems. The stones are traded rough and mostly cut abroad. This is a concept study in the rough stone — not a stocked item, and no origin is certified.",indicativePrice:null,availability:"unverified"},{slug:"kohistan-peridot",name:"Kohistan Peridot",collection:"stones-of-the-north",featured:!1,shortDescription:"Peridot from the Sapat watershed.",description:"Gem-quality peridot — zabarjad — is documented from the Parla Sapat area on the watershed between the Kaghan valley and Kohistan, emerging in the mid-1990s and now internationally regarded. The mines sit below the snowline with a short summer season, and the rough is traded through Peshawar. This is a concept study in the rough crystal — not a stocked item, and no origin is certified.",indicativePrice:null,availability:"unverified"},{slug:"tourmaline",name:"Tourmaline",collection:"stones-of-the-north",featured:!1,shortDescription:"Rough tourmaline from the northern pegmatites.",description:"Tourmaline is documented among the pegmatite gemstones of Gilgit-Baltistan — Shigar, Haramosh and Stak — mined by small-scale family workings and traded rough through Gilgit and Skardu. This is a concept study in the rough crystal — not a stocked item, and no origin is certified.",indicativePrice:null,availability:"unverified"}];function n(e){return a.find(t=>t.id===e)}function s(e){return o.find(t=>t.slug===e)}function r(e){return e&&"all"!==e?o.filter(t=>t.collection===e):o}let l="Unverified"}}]);